def page(records, cursor=None, limit=10):
    if limit < 1:
        raise ValueError('limit')
    ordered = sorted(records, key=lambda x: (x['timestamp'], x['id']))
    if cursor is not None:
        # When a cursor is provided, we want to skip all records that would have
        # already been returned in previous pages, including those with same timestamp

        # Find the index of the last record whose timestamp equals the cursor
        # (because there might be multiple records with that timestamp)
        start_index = 0
        for i, record in enumerate(ordered):
            if record['timestamp'] == cursor:
                # If this is the last element with the current cursor timestamp,
                # we need to skip all of them to get to next elements
                if i == len(ordered) - 1:
                    start_index = i + 1
                    break
                elif ordered[i+1]['timestamp'] != cursor:
                    # This is the last record with this timestamp
                    start_index = i + 1
                    break
            elif record['timestamp'] > cursor:
                # Record that comes after the cursor in sort order
                start_index = i
                break

        ordered = ordered[start_index:]
    items = ordered[:limit]
    next_cursor = items[-1]['timestamp'] if len(ordered) > limit else None
    return {'items': items, 'next_cursor': next_cursor}
